mapper.select:
select start_user_id as userId, start_user_name as userName, organization_name as organizationName, count(1) as totalNumber, sum(IF(result = 'PASS', 1, 0)) as dealNumber, sum(IF(result IN ('', 'ACTIVE') or result is null, 1, 0)) as waitNumber,
SUM(TIMESTAMPDIFF(MINUTE, create_time, update_time)) as totalWaitTime
SUM(EXTRACT(EPOCH FROM AGE(update_time, create_time))/60) as totalWaitTime
SUM(DATEDIFF(MINUTE, create_time, update_time)) as totalWaitTime
SUM(TIMESTAMPDIFF(MINUTE, create_time, update_time)) as totalWaitTime
from process_instance_running where (result in ('PASS', 'ACTIVE') or result is null)
and application_code = #{parame.applicationCode}
and business_type = #{parame.businessType}
and create_time >= #{parame.period.begin} and create_time <= #{parame.period.end}
and start_user_id in
#{item}
and start_user_name like concat('%',#{parame.keyword},'%')
GROUP BY start_user_id ORDER BY totalNumber desc

select `start_user_id` as userId, `start_user_name` as userName, `organization_name` as organizationName, count(1) as totalNumber, sum(IF(`result` = 'PASS', 1, 0)) as dealNumber, sum(IF(`result` IN ('', 'ACTIVE') or `result` is null, 1, 0)) as waitNumber,
SUM(TIMESTAMPDIFF(MINUTE, create_time, update_time)) as totalWaitTime
SUM(EXTRACT(EPOCH FROM AGE(update_time, create_time))/60) as totalWaitTime
SUM(DATEDIFF(MINUTE, create_time, update_time)) as totalWaitTime
SUM(TIMESTAMPDIFF(MINUTE, create_time, update_time)) as totalWaitTime
from `process_instance_running` where (`result` in ('PASS', 'ACTIVE') or `result` is null)
and `application_code` = #{parame.applicationCode}
and `business_type` = #{parame.businessType}
and `create_time` >= #{parame.period.begin} and `create_time` <= #{parame.period.end}
and `start_user_id` in
#{item}
and `start_user_name` like concat('%',#{parame.keyword},'%')
GROUP BY `start_user_id` ORDER BY totalNumber desc

SELECT pir.business_type, ffb.business_type_name, ffg.name AS formGroupName, count( DISTINCT pir.id ) AS totalNumber, sum( IF ( pir.result IN ( '', 'ACTIVE' ) OR pir.result IS NULL, 1, 0 )) AS processNumber, sum( IF ( pir.result = 'REJECT', 1, 0 )) AS rejectNumber, sum( IF ( pir.result = 'UNDO', 1, 0 )) AS undoNumber, sum( IF ( pir.result = 'PASS', 1, 0 )) AS dealNumber FROM process_instance_running pir LEFT JOIN form_flow_business ffb ON pir.business_type = ffb.business_type LEFT JOIN form_flow ff ON ffb.form_flow_id = ff.id LEFT JOIN form_flow_group ffg ON ff.form_group_id = ffg.id
and `pir`.create_time BETWEEN #{query.period.begin} AND #{query.period.end}
and pir.business_type= #{query.businessType}
and pir.application_code= #{query.applicationCode}
and pir.business_type in
#{item}
GROUP BY pir.business_type, ffb.business_type_name, ffg.name
